package cn.xi.cloudwidget;
import android.app.*;
import android.appwidget.*;
import android.content.*;
import android.graphics.*;
import android.graphics.drawable.BitmapDrawable;
import android.os.*;
import android.util.SizeF;
import android.view.*;
import android.widget.*;

public class MiniChecks extends StretchChecks {
    @Override public void onStart(){if(!"mini".equals(args.getString("phase"))){super.onStart();return;}Bundle output=new Bundle();try{c=getTargetContext();Store store=new Store(c);
        MainActivity home=(MainActivity)startActivitySync(new Intent(c,PortraitMainActivity.class).putExtra("page",0).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));waitForIdleSync();View entry=find(home.getWindow().getDecorView(),"新建：1×1 素材");check(entry!=null,"home exposes dedicated 1x1 material entry");ActivityMonitor monitor=addMonitor(EditorActivity.class.getName(),null,false);main(entry::performClick);Activity opened=monitor.waitForActivityWithTimeout(5000);removeMonitor(monitor);check(opened instanceof EditorActivity,"1x1 entry opens independent editor");EditorActivity editor=(EditorActivity)opened;waitForIdleSync();Card draft=(Card)field("card").get(editor);check(draft.shape==2&&draft.type==1&&draft.bgMode==1&&draft.title.isEmpty()&&draft.body.isEmpty()&&draft.stickers.length()==0,"new 1x1 defaults to transparent material without clock or text");main(editor::save);check(!editor.isFinishing()&&store.get(draft.id)==null,"empty invisible material tile cannot be saved accidentally");
        AlertDialog[] picker={null};main(()->picker[0]=AssetPicker.show(editor,a->editor.add(a.ref)));waitForIdleSync();AssetStore.Asset asset=new AssetStore(c).get("builtin:cream-read");View tile=find(picker[0].getWindow().getDecorView(),asset.name+"，"+asset.pack);check(tile!=null,"native material picker contains built-in artwork");main(tile::performClick);waitForIdleSync();check(draft.stickers.length()==1&&draft.stickers.getJSONObject(0).getString("asset").equals(asset.ref),"native material selection populates one sticker");check(draft.stickers.getJSONObject(0).getDouble("x")==.5&&draft.stickers.getJSONObject(0).getDouble("y")==.5&&draft.stickers.getJSONObject(0).getDouble("width")==.9,"1x1 material starts centered and fitted");main(()->named(editor.getWindow().getDecorView(),"保存").performClick());check(store.get(draft.id).shape==2&&store.get(draft.id).bgMode==1,"1x1 selection persists through actual Save");
        MiniHostActivity host=(MiniHostActivity)startActivitySync(new Intent(c,MiniHostActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));waitForIdleSync();check(host.ids.size()==2,"two native 1x1 widget instances bind successfully");
        for(int n=0;n<2;n++){int id=host.ids.get(n),index=n;AppWidgetHostView view=host.actual.get(n);ImageView image=ready(view);AppWidgetProviderInfo info=AppWidgetManager.getInstance(c).getAppWidgetInfo(id);check(WidgetProvider.shape(info)==2&&info.minWidth<=Ui.dp(c,60)&&info.minHeight<=Ui.dp(c,60),"provider advertises a genuinely small 1x1 minimum "+index);check(view.findViewById(R.id.clock_group).getVisibility()==View.GONE,"1x1 material contains no visible clock "+index);float[] transform=imageMatrix(image);check(Math.abs(transform[Matrix.MSCALE_X]-transform[Matrix.MSCALE_Y])<.001,"1x1 native material remains proportional "+index);Bitmap bitmap=((BitmapDrawable)image.getDrawable()).getBitmap();int transparent=0,visible=0;for(int y=0;y<bitmap.getHeight();y++)for(int x=0;x<bitmap.getWidth();x++){int alpha=Color.alpha(bitmap.getPixel(x,y));if(alpha==0)transparent++;if(alpha>200)visible++;}check(transparent>100&&visible>50&&Color.alpha(bitmap.getPixel(0,0))==0,"1x1 renderer preserves transparency without baking preview checkerboard "+index);
            monitor=addMonitor(EditorActivity.class.getName(),null,false);main(()->view.findViewById(R.id.hits).performClick());Activity result=monitor.waitForActivityWithTimeout(5000);removeMonitor(monitor);check(result instanceof EditorActivity,"small 1x1 root click opens editor "+index);EditorActivity configured=(EditorActivity)result;waitForIdleSync();Card loaded=(Card)field("card").get(configured);this.report.append("MINI expectedId="+id+" actualId="+configured.getIntent().getIntExtra(AppWidgetManager.EXTRA_APPWIDGET_ID,-1)+" binding="+store.binding(id)+" card="+loaded.json()+"\n");check(loaded.id.equals(store.binding(id))&&loaded.shape==2&&loaded.type==1&&loaded.stickers.length()==1,"bound 1x1 retains its material configuration "+index);SizeF measured=WidgetGeometry.measured(c,id,new SizeF(58,66));check(measured!=null&&measured.getWidth()<80&&measured.getHeight()<80,"sub-80dp actual widget bounds are accepted "+index);main(configured::finish);waitForIdleSync();SystemClock.sleep(300);
        }
        Card first=store.get(store.binding(host.ids.get(0))),second=store.get(store.binding(host.ids.get(1)));String secondJson=second.json().toString();first.addSticker("builtin:blue-sprig");store.save(first);check(first.stickers.length()==1&&store.get(second.id).json().toString().equals(secondJson),"replacing a 1x1 material leaves another instance unchanged");check(WidgetProvider.provider(2)==MiniWidget.class,"saved 1x1 cards pin to the dedicated provider");store.stagePin(first);check(store.takePin(c,host.ids.get(1)).equals(first.id),"1x1 system configuration uses the correct staged shape");store.clearPin();
        output.putString("stream",report+"Checks passed this run: "+count+"\n");finish(Activity.RESULT_OK,output);
    }catch(Throwable e){output.putString("stream",report+"FAIL "+android.util.Log.getStackTraceString(e));finish(Activity.RESULT_CANCELED,output);}}
}
